void test_shunting_yard_2()
  {
  cout << "=====test_shunting_yard_2()===== " << endl;
  // Create an example input queue
  Queue<Token*> input;
  cout << "Input: sin x" << endl;
  // Add tokens for variable and functions (example expression: "sin(x) + 3 * x")
  input.push(new Function("sin"));
  input.push(new Variable("x"));

  // Create a ShuntingYard object
  ShuntingYard sy;

  //Get the postfix notation
  Queue<Token*> postfix = sy.postfix(input);
  RPN rpn(postfix);
  cout << "Test result:  = " << rpn(90) << endl;

  }


void test_split(const string& expression)
  {
  cout << "\n===Test 3: split===\n" << endl;
  // create a TK_string object
  TK_string tk;
  bool hasParenError = false;
  vector<Token*> tokens = tk.split(expression);

  // print the expression and the tokens
  cout << "Expression: " << expression << endl;
  cout << "Tokens: ";
  for (const auto& token : tokens)
    {
    cout << *token << " ";
    }
  cout << endl;

  // relesase memory
  for (auto token : tokens)
    {
    delete token;
    }
  }



int main(int argc, char **argv)
  {
  ::testing::InitGoogleTest(&argc, argv);
  cout << "\n\n----------running basic_test.cpp---------\n\n" << endl;
  test_shunting_yard_2();
  test_shunting_yard_1();
  cout << "test:sinx" << endl;
  test_split("sinx");
  cout << "2x+3" << endl;
  test_split("2x+3");
  cout << "test(sqrt(x) + 5 ^ 2)" << endl;
  test_split("sqrt(x) + 5 ^ 2");
  test_split("tan(30) + cot(60)");
  test_split("log(100) % exp(2)");
  test_split("abs(-5) + abs(5)");
  test_split("max(10, 20) + min(5, 10)");

  return RUN_ALL_TESTS();
  }

